// Evolution speaks Baileys. The app speaks its own contract. This is the only
// node that knows both, on purpose: when Evolution changes shape, one node
// changes.
const input = $input.first().json;
const body = input.body ?? input;
const data = body.data ?? {};
const key = data.key ?? {};

// Our own outgoing messages come back through the same event.
if (key.fromMe) return [];

const m = data.message ?? {};
const text = m.conversation ?? m.extendedTextMessage?.text ?? '';
const caption = m.imageMessage?.caption ?? m.videoMessage?.caption
  ?? m.documentMessage?.caption ?? '';

let type = 'text';
if (m.imageMessage) type = 'image';
else if (m.audioMessage) type = 'audio';
else if (m.videoMessage) type = 'video';
else if (m.documentMessage) type = 'document';

// Nothing to read and nothing to look at. Not an error, just not a change.
if (!text && !caption && type === 'text') return [];

const jid = String(key.remoteJid ?? '');
// Groups end @g.us and carry the real sender in `participant`. A group message
// signed by the group would resolve to no user at all.
const sender = jid.endsWith('@g.us') ? String(key.participant ?? '') : jid;

const payload = {
  idempotency_key: 'evolution:' + (key.id ?? ''),
  received_at: new Date((Number(data.messageTimestamp) || Date.now() / 1000) * 1000).toISOString(),
  sender: {
    phone: '+' + sender.split('@')[0].split(':')[0],
    display_name: data.pushName || undefined,
  },
  message: {
    type,
    text: text || undefined,
    caption: caption || undefined,
    media: [],
  },
};

return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// With `simple: false` the Gmail Trigger already parses the message: from, to,
// subject, text, date. It does NOT return the raw Gmail API envelope, so
// reading payload.headers here — which is what the API returns — would find
// nothing and every captured email would arrive with an empty sender.
const m = $input.first().json;

// `from` arrives as `Name <address@host>` or bare. Take the address either way.
const raw = String(m.from ?? '');
const match = raw.match(/<([^>]+)>/);
const address = (match ? match[1] : raw).trim().toLowerCase();
const name = match ? raw.slice(0, raw.indexOf('<')).replace(/["']/g, '').trim() : '';

const list = (v) => (Array.isArray(v) ? v : String(v ?? '').split(','))
  .map((x) => String(x).trim())
  .filter(Boolean);

const payload = {
  idempotency_key: 'gmail:' + (m.id ?? m.messageId ?? ''),
  received_at: new Date(m.date ?? Date.now()).toISOString(),
  from: { address, name: name || undefined },
  to: list(m.to),
  cc: list(m.cc),
  subject: m.subject ?? '',
  body_text: m.text ?? m.textAsHtml ?? '',
  attachments: [],
};

return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// The project code comes from the folder name, which is where the app puts it
// (`DXB-001 — Dubai Office Fit-Out`). If it cannot be read, send it anyway and
// let the app reject it: a 4xx that names the file beats a document filed
// against a project somebody guessed at.
const f = $input.first().json;
const name = f.name ?? '';
const parentName = f.parentFolderName ?? f.parents?.[0]?.name ?? '';
const code = (parentName.match(/^[A-Z]{2,4}-\d{3}/) ?? name.match(/^[A-Z]{2,4}-\d{3}/) ?? [''])[0];

const payload = {
  idempotency_key: 'drive:' + (f.id ?? ''),
  project_code: code,
  document_name: name,
  document_type: 'other',
  external_file_id: f.id,
  source_url: f.webViewLink || undefined,
};

return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// The app treats its own outbound request as 'queued', never 'sent'. This
// call is the only thing that can move a notification to delivered, and the
// only evidence that a message actually left the building.
const src = $('D3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'sent',
  external_message_id: $input.first().json.id ?? undefined,
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// A failed send is recorded as failed, with the reason. Silence here would
// leave a notification pending for ever and nobody would know it never went.
const src = $('D3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'failed',
  failure_reason: String($input.first().json.error?.message ?? 'Gmail send failed').slice(0, 400),
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// The app treats its own outbound request as 'queued', never 'sent'. This
// call is the only thing that can move a notification to delivered, and the
// only evidence that a message actually left the building.
const src = $('E3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'sent',
  external_message_id: $input.first().json.key?.id ?? undefined,
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

const src = $('E3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'failed',
  failure_reason: String($input.first().json.error?.message ?? 'Evolution send failed').slice(0, 400),
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

const e = $input.first().json;
const node = e.execution?.lastNodeExecuted ?? '';
const lane = (node.match(/^([A-Z])\d/) ?? [])[1] ?? '?';

const LANES = {
  A: 'WhatsApp capture', B: 'Email capture', C: 'Document watch',
  D: 'Email out', E: 'WhatsApp out', S: 'Scheduled jobs',
  F: 'Client follow-up', G: 'Weekly report',
};

return [{ json: {
  lane,
  lane_name: LANES[lane] ?? 'Unknown lane',
  node,
  message: e.execution?.error?.message ?? 'No message',
  workflow: e.workflow?.name ?? '',
  execution_url: e.execution?.url ?? '',
  at: new Date().toISOString(),
} }];
